def evaluate_formula(text):
    if not isinstance(text, str):
        raise TypeError("text must be a string")

    tokens = []
    pos = 0
    ascii_whitespace = " \t\n\r\v\f"

    while pos < len(text):
        char = text[pos]
        if char in ascii_whitespace:
            pos += 1
        elif "0" <= char <= "9":
            end = pos + 1
            while end < len(text) and "0" <= text[end] <= "9":
                end += 1
            tokens.append(int(text[pos:end]))
            pos = end
        elif char in "+-*/()":
            tokens.append(char)
            pos += 1
        else:
            pos += 1

    if not tokens:
        raise ValueError("empty expression")

    index = 0

    def primary():
        nonlocal index
        if index >= len(tokens):
            raise ValueError("missing operand")

        token = tokens[index]
        if isinstance(token, int):
            index += 1
            return token

        if token == "(":
            index += 1
            value = expression()
            if index >= len(tokens) or tokens[index] != ")":
                raise ValueError("unbalanced parentheses")
            index += 1
            return value

        raise ValueError("missing operand")

    def term():
        nonlocal index
        value = primary()
        while index < len(tokens) and tokens[index] in ("*", "/"):
            operator = tokens[index]
            index += 1
            right = primary()
            if operator == "*":
                value = value * right
            else:
                value = value / right
        return value

    def expression():
        nonlocal index
        value = term()
        while index < len(tokens) and tokens[index] in ("+", "-"):
            operator = tokens[index]
            index += 1
            right = term()
            if operator == "+":
                value = value + right
            else:
                value = value - right
        return value

    result = expression()
    if index != len(tokens):
        raise ValueError("unexpected token")
    return result

